        assertTrue(paxGNUSparseInputStream.canReadEntryData(paxGNUEntry));
        try (TarArchiveInputStream oldGNUSparseInputStream = new TarArchiveInputStream(Files.newInputStream(oldGNUSparseTar.toPath()))) {
