            assertTrue(oldGNUSparseInputStream.canReadEntryData(oldGNUEntry));
            assertArrayEquals(IOUtils.toByteArray(oldGNUSparseInputStream), IOUtils.toByteArray(paxGNUSparseInputStream));
        }
    }
