@Test
public void testReparse() throws Exception {
    // CRC manually calculated, sorry
    byte[] data = { // CRC
    (byte) 0xC6, // CRC
    0x02, // CRC
    0x78, // CRC
    (byte) 0xB6, // mode
    0123, // mode
    (byte) 0x80, // link length
    0, // link length
    0, // link length
    0, // link length
    0, 5, 0, 6, // uid, gid
    0 };
    AsiExtraField a = new AsiExtraField();
    a.parseFromLocalFileData(data, 0, data.length);
    assertEquals("length plain file", data.length, a.getLocalFileDataLength().getValue());
    assertFalse("plain file, no link", a.isLink());
    assertFalse("plain file, no dir", a.isDirectory());
    assertEquals("mode plain file", FILE_FLAG | 0123, a.getMode());
    assertEquals("uid plain file", 5, a.getUserId());
    assertEquals("gid plain file", 6, a.getGroupId());
    data = new byte[] { // CRC
    0x75, // CRC
    (byte) 0x8E, // CRC
    0x41, // CRC
    (byte) 0xFD, // mode
    0123, // mode
    (byte) 0xA0, // link length
    4, // link length
    0, // link length
    0, // link length
    0, // uid, gid
    5, // uid, gid
    0, // uid, gid
    6, // uid, gid
    0, (byte) 't', (byte) 'e', (byte) 's', (byte) 't' };
    a = new AsiExtraField();
    a.parseFromLocalFileData(data, 0, data.length);
    assertEquals("length link", data.length, a.getLocalFileDataLength().getValue());
    assertTrue("link, is link", a.isLink());
    assertFalse("link, no dir", a.isDirectory());
    assertEquals("mode link", LINK_FLAG | 0123, a.getMode());
    assertEquals("uid link", 5, a.getUserId());
    assertEquals("gid link", 6, a.getGroupId());
    assertEquals("test", a.getLinkedFile());
    data = new byte[] { // CRC
    (byte) 0x8E, // CRC
    0x01, // CRC
    (byte) 0xBF, // CRC
    (byte) 0x0E, // mode
    0123, // mode
    (byte) 0x40, // link
    0, // link
    0, // link
    0, // link
    0, 5, 0, 6, // uid, gid
    0 };
    a = new AsiExtraField();
    a.parseFromLocalFileData(data, 0, data.length);
    assertEquals("length dir", data.length, a.getLocalFileDataLength().getValue());
    assertFalse("dir, no link", a.isLink());
    assertTrue("dir, is dir", a.isDirectory());
    assertEquals("mode dir", DIR_FLAG | 0123, a.getMode());
    assertEquals("uid dir", 5, a.getUserId());
    assertEquals("gid dir", 6, a.getGroupId());
    data = new byte[] { // bad CRC
    0, // bad CRC
    0, // bad CRC
    0, // bad CRC
    0, // mode
    0123, // mode
    (byte) 0x40, // link
    0, // link
    0, // link
    0, // link
    0, 5, 0, 6, // uid, gid
    0 };
    a = new AsiExtraField();
    try {
        a.parseFromLocalFileData(data, 0, data.length);
        fail("should raise bad CRC exception");
    } catch (final Exception e) {
        assertEquals("Bad CRC checksum, expected 0 instead of ebf018e", e.getMessage());
    }
}

