@Test
public void testWriteCDSizeAndDisk() {
    final Zip64ExtendedInformationExtraField f = new Zip64ExtendedInformationExtraField(SIZE, CSIZE, null, DISK);
    assertEquals(new ZipShort(20), f.getCentralDirectoryLength());
