@Test
public void testZip64ModeAlwaysWithCompatibility() throws Throwable {
    final File inputFile = getFile("test3.xml");
    // with Zip64Mode.AlwaysWithCompatibility, the relative header offset and disk number
    // start will not be set in extra fields
    final File zipUsingModeAlwaysWithCompatibility = buildZipWithZip64Mode("testZip64ModeAlwaysWithCompatibility-output-1", Zip64Mode.AlwaysWithCompatibility, inputFile);
    final ZipFile zipFileWithAlwaysWithCompatibility = new ZipFile(zipUsingModeAlwaysWithCompatibility);
    ZipArchiveEntry entry = zipFileWithAlwaysWithCompatibility.getEntries().nextElement();
    for (final ZipExtraField extraField : entry.getExtraFields()) {
        if (!(extraField instanceof Zip64ExtendedInformationExtraField)) {
            continue;
        }
        assertNull(((Zip64ExtendedInformationExtraField) extraField).getRelativeHeaderOffset());
        assertNull(((Zip64ExtendedInformationExtraField) extraField).getDiskStartNumber());
    }
    // with Zip64Mode.Always, the relative header offset and disk number start will be
    // set in extra fields
    final File zipUsingModeAlways = buildZipWithZip64Mode("testZip64ModeAlwaysWithCompatibility-output-2", Zip64Mode.Always, inputFile);
    final ZipFile zipFileWithAlways = new ZipFile(zipUsingModeAlways);
    entry = zipFileWithAlways.getEntries().nextElement();
    for (final ZipExtraField extraField : entry.getExtraFields()) {
        if (!(extraField instanceof Zip64ExtendedInformationExtraField)) {
            continue;
        }
        assertNotNull(((Zip64ExtendedInformationExtraField) extraField).getRelativeHeaderOffset());
        assertNotNull(((Zip64ExtendedInformationExtraField) extraField).getDiskStartNumber());
    }
}

/**
 * test handling of extra fields
 */
@Test
public void testExtraFields() {
    final AsiExtraField a = new AsiExtraField();
    a.setDirectory(true);
    a.setMode(0755);
    final UnrecognizedExtraField u = new UnrecognizedExtraField();
    u.setHeaderId(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
    u.setLocalFileDataData(ByteUtils.EMPTY_BYTE_ARRAY);
    final ZipArchiveEntry ze = new ZipArchiveEntry("test/");
    ze.setExtraFields(new ZipExtraField[] { a, u });
    final byte[] data1 = ze.getExtra();
    ZipExtraField[] result = ze.getExtraFields();
    assertEquals("first pass", 2, result.length);
    assertSame(a, result[0]);
    assertSame(u, result[1]);
    final UnrecognizedExtraField u2 = new UnrecognizedExtraField();
    u2.setHeaderId(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
    u2.setLocalFileDataData(new byte[] { 1 });
    ze.addExtraField(u2);
    final byte[] data2 = ze.getExtra();
    result = ze.getExtraFields();
    assertEquals("second pass", 2, result.length);
    assertSame(a, result[0]);
    assertSame(u2, result[1]);
    assertEquals("length second pass", data1.length + 1, data2.length);
    final UnrecognizedExtraField u3 = new UnrecognizedExtraField();
    u3.setHeaderId(new ZipShort(2));
    u3.setLocalFileDataData(new byte[] { 1 });
    ze.addExtraField(u3);
    result = ze.getExtraFields();
    assertEquals("third pass", 3, result.length);
    ze.removeExtraField(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
    final byte[] data3 = ze.getExtra();
    result = ze.getExtraFields();
    assertEquals("fourth pass", 2, result.length);
    assertSame(a, result[0]);
    assertSame(u3, result[1]);
    assertEquals("length fourth pass", data2.length, data3.length);
    try {
        ze.removeExtraField(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
        fail("should be no such element");
    } catch (final java.util.NoSuchElementException nse) {
    }
}

/**
 * test handling of extra fields via central directory
 */
@Test
public void testExtraFieldMerging() {
    final AsiExtraField a = new AsiExtraField();
    a.setDirectory(true);
    a.setMode(0755);
    final UnrecognizedExtraField u = new UnrecognizedExtraField();
    u.setHeaderId(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
    u.setLocalFileDataData(ByteUtils.EMPTY_BYTE_ARRAY);
    final ZipArchiveEntry ze = new ZipArchiveEntry("test/");
    ze.setExtraFields(new ZipExtraField[] { a, u });
    // merge
    // Header-ID 1 + length 1 + one byte of data
    final byte[] b = ExtraFieldUtilsTest.UNRECOGNIZED_HEADER.getBytes();
    ze.setCentralDirectoryExtra(new byte[] { b[0], b[1], 1, 0, 127 });
    ZipExtraField[] result = ze.getExtraFields();
    assertEquals("first pass", 2, result.length);
    assertSame(a, result[0]);
    assertEquals(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER, result[1].getHeaderId());
    assertEquals(new ZipShort(0), result[1].getLocalFileDataLength());
    assertEquals(new ZipShort(1), result[1].getCentralDirectoryLength());
    // add new
    // Header-ID 2 + length 0
    ze.setCentralDirectoryExtra(new byte[] { 2, 0, 0, 0 });
    result = ze.getExtraFields();
    assertEquals("second pass", 3, result.length);
    // merge
    // Header-ID 2 + length 1 + one byte of data
    ze.setExtra(new byte[] { 2, 0, 1, 0, 127 });
    result = ze.getExtraFields();
    assertEquals("third pass", 3, result.length);
    assertSame(a, result[0]);
    assertEquals(new ZipShort(2), result[2].getHeaderId());
    assertEquals(new ZipShort(1), result[2].getLocalFileDataLength());
    assertEquals(new ZipShort(0), result[2].getCentralDirectoryLength());
}

/**
 * test handling of extra fields
 */
@Test
public void testAddAsFirstExtraField() {
    final AsiExtraField a = new AsiExtraField();
    a.setDirectory(true);
    a.setMode(0755);
    final UnrecognizedExtraField u = new UnrecognizedExtraField();
    u.setHeaderId(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
    u.setLocalFileDataData(ByteUtils.EMPTY_BYTE_ARRAY);
    final ZipArchiveEntry ze = new ZipArchiveEntry("test/");
    ze.setExtraFields(new ZipExtraField[] { a, u });
    final byte[] data1 = ze.getExtra();
    final UnrecognizedExtraField u2 = new UnrecognizedExtraField();
    u2.setHeaderId(ExtraFieldUtilsTest.UNRECOGNIZED_HEADER);
    u2.setLocalFileDataData(new byte[] { 1 });
    ze.addAsFirstExtraField(u2);
    final byte[] data2 = ze.getExtra();
    ZipExtraField[] result = ze.getExtraFields();
    assertEquals("second pass", 2, result.length);
    assertSame(u2, result[0]);
    assertSame(a, result[1]);
    assertEquals("length second pass", data1.length + 1, data2.length);
    final UnrecognizedExtraField u3 = new UnrecognizedExtraField();
    u3.setHeaderId(new ZipShort(2));
    u3.setLocalFileDataData(new byte[] { 1 });
    ze.addAsFirstExtraField(u3);
    result = ze.getExtraFields();
    assertEquals("third pass", 3, result.length);
    assertSame(u3, result[0]);
    assertSame(u2, result[1]);
    assertSame(a, result[2]);
}

@Test
public void testUnixMode() {
    ZipArchiveEntry ze = new ZipArchiveEntry("foo");
    assertEquals(0, ze.getPlatform());
    ze.setUnixMode(0755);
    assertEquals(3, ze.getPlatform());
    assertEquals(0755, (ze.getExternalAttributes() >> 16) & 0xFFFF);
    assertEquals(0, ze.getExternalAttributes() & 0xFFFF);
    ze.setUnixMode(0444);
    assertEquals(3, ze.getPlatform());
    assertEquals(0444, (ze.getExternalAttributes() >> 16) & 0xFFFF);
    assertEquals(1, ze.getExternalAttributes() & 0xFFFF);
    ze = new ZipArchiveEntry("foo/");
    assertEquals(0, ze.getPlatform());
    ze.setUnixMode(0777);
    assertEquals(3, ze.getPlatform());
    assertEquals(0777, (ze.getExternalAttributes() >> 16) & 0xFFFF);
    assertEquals(0x10, ze.getExternalAttributes() & 0xFFFF);
    ze.setUnixMode(0577);
    assertEquals(3, ze.getPlatform());
    assertEquals(0577, (ze.getExternalAttributes() >> 16) & 0xFFFF);
    assertEquals(0x11, ze.getExternalAttributes() & 0xFFFF);
}

