        zo.putArchiveEntry(ze);
        zo.write(new byte[] { 1, 2, 3, 4 });
        zo.closeArchiveEntry();
        zo.close();
        o.close();
        o = null;
        zf = new ZipFile(f);
        ze = zf.getEntry("foo");
        assertNotNull(ze);
        i = zf.getInputStream(ze);
        final byte[] b = new byte[4];
        assertEquals(4, i.read(b));
        assertEquals(-1, i.read());
    } finally {
        if (o != null) {
            o.close();
        }
        if (i != null) {
            i.close();
        }
        f.delete();
    }
}

