    bTest[3] = new byte[] { 1, 2, 3 };
    bTest[4] = new byte[] { 1, 2, 3, 4 };
    bTest[5] = new byte[] { 1, 2, 3, 4, 5 };
    final byte[][] rTest = new byte[6][];
    rTest[0] = new byte[] {};
    rTest[1] = new byte[] { 1 };
    rTest[2] = new byte[] { 2, 1 };
    rTest[3] = new byte[] { 3, 2, 1 };
    rTest[4] = new byte[] { 4, 3, 2, 1 };
    rTest[5] = new byte[] { 5, 4, 3, 2, 1 };
