@Test
public void testCorruptedInput() throws Exception {
    InputStream in = null;
    OutputStream out = null;
    CompressorInputStream cin = null;
    try {
        in = Files.newInputStream(getFile("bla.tgz").toPath());
        out = new ByteArrayOutputStream();
        IOUtils.copy(in, out);
        in.close();
        out.close();
        final byte[] data = ((ByteArrayOutputStream) out).toByteArray();
        in = new ByteArrayInputStream(data, 0, data.length - 1);
        cin = new CompressorStreamFactory().createCompressorInputStream("gz", in);
        out = new ByteArrayOutputStream();
        try {
            IOUtils.copy(cin, out);
            fail("Expected an exception");
        } catch (final IOException ioex) {
            // the whole point of the test
        }
    } finally {
        if (out != null) {
            out.close();
        }
        if (cin != null) {
            cin.close();
        }
        if (in != null) {
            in.close();
        }
    }
}

@Test
